"""Native fixture: production queues, shared memory, serializer, batches and waits.

Only logger/options/peer callbacks and application dispatch are adapters. Sources
are extracted into an isolated directory and hashed; production is never edited.
"""
import argparse
import hashlib
import json
from pathlib import Path
from generate_buffer_contract_test import method

ROOT = Path(__file__).resolve().parents[1]
FILES = (
    'util_common.h', 'util_commands.h', 'util_circularqueue.h', 'util_circularbuffer.h',
    'util_atomiccircularqueue.h', 'util_ipcchannel.h', 'util_sharedmemory.h', 'util_sharedmemory.cpp',
    'util_semaphore.h', 'util_semaphore.cpp', 'util_guid.h', 'api_wait_diagnostics.h',
    'data_diagnostics.h', 'data_diagnostics.cpp', 'exception_diagnostics.h', 'exception_diagnostics.cpp',
    'queue_wait_diagnostics.h', 'runtime_observation.h', 'util_scopedlock.h', 'device_reset.h',
    'data_ring_contract.h',
)


def prepare_support(source, output):
    util = source / 'bridge/src/util'
    output.mkdir(parents=True, exist_ok=True)
    hashes = {}
    for name in FILES:
        text = (util / name).read_text(encoding='utf-8')
        hashes[name] = hashlib.sha256(text.encode()).hexdigest()
        if name == 'util_semaphore.cpp':
            text = '#include "ipc_wait_injection.h"\n' + text
        if name == 'util_ipcchannel.h':
            text = text.replace('#include "util_blockingcircularqueue.h"','')  # unused alternative
        (output / name).write_text(text, encoding='utf-8')
    (output / 'version.h').write_text('#define BRIDGE_VERSION \"native-production-fixture\"\n',encoding='utf-8')
    (output / 'log').mkdir(exist_ok=True)
    (output / 'log/log.h').write_text('''#pragma once
#include <cstdlib>
#include <string>
namespace bridge_util { enum class LogLevel { Trace }; }
template<typename... T> std::string format_string(const char*, T...) { return {}; }
struct Logger {
 static bool isEnabled(bridge_util::LogLevel) { return false; }
 static void info(const std::string&) {} static void warn(const std::string&) {} static void err(const std::string&) {}
 template<typename T> static void traceLazy(T&&) {} template<typename T> static void debugLazy(T&&) {}
 [[noreturn]] static void errLogMessageBoxAndExit(const std::string&) { std::abort(); }
};
''',encoding='utf-8')
    (output / 'log/log_strings.h').write_text('''#pragma once
namespace logger_strings {
inline const char* MultipleActiveCommands="nested";
inline const char* OutOfBufferMemory="capacity"; inline const char* OutOfBufferMemory1="capacity";
inline std::string bufferNameToOption(const std::string&) { return {}; }
}
''',encoding='utf-8')
    (output / 'config').mkdir(exist_ok=True)
    (output / 'config/global_options.h').write_text('''#pragma once
#include <cstdint>
struct GlobalOptions {
 inline static uint32_t timeout = 2000;
 inline static uint32_t retries = 2;
 static uint32_t getCommandTimeout() { return timeout; }
 static uint32_t getCommandRetries() { return retries; }
 static uint32_t getSemaphoreTimeout() { return timeout; }
 static uint32_t getAckTimeout() { return timeout; }
 static bool getLogAllCommands() { return false; }
 static bool getInfiniteRetries() { return false; }
};
''',encoding='utf-8')
    return hashes


def generate(source, output):
    hashes = prepare_support(source, output)
    util = source / 'bridge/src/util'
    header = (util / 'util_bridgecommand.h').read_text(encoding='utf-8')
    cpp = (util / 'util_bridgecommand.cpp').read_text(encoding='utf-8')
    for name, text in [('util_bridgecommand.h',header),('util_bridgecommand.cpp',cpp)]:
        hashes[name] = hashlib.sha256(text.encode()).hexdigest()
    bridge = header[header.index('struct BridgeReadFailure'):]
    bridge = bridge[bridge.index('struct BridgeReadFailure'):]
    # Drop response macros before the class: test dispatch verifies each reply directly.
    bridge = bridge.replace('public:\n  static void init(', '''public:
  static void install(WriterChannel* writer, ReaderChannel* reader) {
    s_pWriterChannel=writer; s_pReaderChannel=reader; s_cmdUID=0;
    s_readActive=false; s_readPins.clear();
  }
  static void init(''',1)
    bodies=[]
    for marker in ('DECL_BRIDGE_FUNC(void, reportFault,', 'DECL_BRIDGE_FUNC(bridge_util::Result, waitDataQueue,',
                   'DECL_BRIDGE_FUNC(void, startRead,', 'DECL_BRIDGE_FUNC(void, startPendingRead)',
                   'DECL_BRIDGE_FUNC(void, failRead)', 'DECL_BRIDGE_FUNC(size_t, end_read_data)',
                   'DECL_BRIDGE_FUNC(Header, pop_front)', 'DECL_BRIDGE_FUNC(bridge_util::Result, waitForCommand,'):
        start,end=method(cpp,marker);bodies.append(cpp[start:end])
    prefix=cpp[cpp.index('namespace {'):cpp.index('DECL_BRIDGE_FUNC(void, init,')]
    definitions=cpp[cpp.index('#define DECL_COMMAND_FUNC'):]
    support=(ROOT/'tests/ipc_transport_support.h').read_text(encoding='utf-8')
    generated=support+'\n'+bridge+'\n'+prefix+'\n'+'\n'.join(bodies)+'\n'+definitions+'\n#include "ipc_transport_cases.cpp"\n'
    (output/'ipc_transport.cpp').write_text(generated,encoding='utf-8')
    (output/'source-manifest.json').write_text(json.dumps({'source_sha256':hashes,
      'adapters':['options/logger','peer exit signal','test dispatch','explicit system wait failure injection']},indent=2)+'\n',encoding='utf-8')


if __name__ == '__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source',type=Path,default=ROOT/'.deps/dxvk-remix')
    parser.add_argument('--output',type=Path,default=ROOT/'.deps/ipc-transport')
    args=parser.parse_args();generate(args.source,args.output)
